package com.maramigo.marketplace;
import com.maramigo.accounts.AccountService;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.HttpStatus;
import java.util.*;
/** Personal data and conversations scoped to actual purchases. @author Maram Abbas */
@RestController @Transactional(readOnly=true)
public class CustomerHub {
 private final JdbcTemplate db;public CustomerHub(JdbcTemplate db){this.db=db;}
 public record Profile(@NotNull @Size(max=120) String fullName,@NotNull @Size(max=40) String phone,@NotNull @Size(max=240) String address,@NotNull @Size(max=120) String city){}
 @GetMapping("/api/customer/profile") public Profile profile(@AuthenticationPrincipal AccountService.Principal user){return db.query("SELECT full_name,phone,address,city FROM customer_profiles WHERE user_id=?",(r,n)->new Profile(r.getString(1),r.getString(2),r.getString(3),r.getString(4)),user.id()).stream().findFirst().orElse(new Profile("","","",""));}
 @PutMapping("/api/customer/profile") @Transactional public Profile save(@AuthenticationPrincipal AccountService.Principal user,@Valid @RequestBody Profile p){lockFavorites(user.id());db.update("INSERT INTO customer_profiles(user_id,full_name,phone,address,city) VALUES (?,?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET full_name=excluded.full_name,phone=excluded.phone,address=excluded.address,city=excluded.city",user.id(),p.fullName().trim(),p.phone().trim(),p.address().trim(),p.city().trim());return profile(user);}
 private void lockFavorites(long user){if(db.queryForList("SELECT id FROM users WHERE id=? AND enabled=true FOR UPDATE",user).isEmpty())throw MarketplaceController.fail(HttpStatus.FORBIDDEN,"This account is no longer active.");}
 @GetMapping("/api/customer/favorites") public List<Map<String,Object>> favorites(@AuthenticationPrincipal AccountService.Principal user){return db.queryForList("SELECT p.id,p.name,p.price,p.company_id,c.name AS company_name,c.slug,c.status,p.active FROM favorites f JOIN products p ON p.id=f.product_id JOIN companies c ON c.id=p.company_id WHERE f.user_id=? ORDER BY f.created_at DESC LIMIT 200",user.id());}
 @PutMapping("/api/customer/favorites/{id}") @Transactional public void favorite(@PathVariable long id,@AuthenticationPrincipal AccountService.Principal user){if(db.queryForList("SELECT p.id FROM products p JOIN companies c ON c.id=p.company_id WHERE p.id=? AND p.active=true AND c.status='APPROVED'",id).isEmpty())throw MarketplaceController.fail(HttpStatus.NOT_FOUND,"Product not found.");lockFavorites(user.id());if(Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM favorites WHERE user_id=? AND product_id=?)",Boolean.class,user.id(),id)))return;if(db.queryForObject("SELECT count(*) FROM favorites WHERE user_id=?",Long.class,user.id())>=200)throw MarketplaceController.fail(HttpStatus.CONFLICT,"Your favorites list is full. Remove an item first.");db.update("INSERT INTO favorites(user_id,product_id) VALUES (?,?) ON CONFLICT DO NOTHING",user.id(),id);}
 @DeleteMapping("/api/customer/favorites/{id}") @Transactional public void unfavorite(@PathVariable long id,@AuthenticationPrincipal AccountService.Principal user){lockFavorites(user.id());db.update("DELETE FROM favorites WHERE user_id=? AND product_id=?",user.id(),id);}
 @DeleteMapping("/api/customer/favorites") @Transactional public void clear(@AuthenticationPrincipal AccountService.Principal user){lockFavorites(user.id());db.update("DELETE FROM favorites WHERE user_id=?",user.id());}
 @GetMapping("/api/customer/stores") public List<Map<String,Object>> bought(@AuthenticationPrincipal AccountService.Principal user){return db.queryForList("SELECT DISTINCT c.id,c.name,c.slug FROM order_items i JOIN orders o ON o.id=i.order_id JOIN companies c ON c.id=i.company_id WHERE o.user_id=? ORDER BY c.id",user.id());}
 @GetMapping("/api/customer/offers") public List<Map<String,Object>> offers(@AuthenticationPrincipal AccountService.Principal user){return db.queryForList("SELECT f.id,f.title,f.body,f.ends_at,c.name,c.slug FROM store_offers f JOIN companies c ON c.id=f.company_id WHERE c.status='APPROVED' AND f.starts_at<=CURRENT_TIMESTAMP AND f.ends_at>CURRENT_TIMESTAMP AND EXISTS(SELECT 1 FROM order_items i JOIN orders o ON o.id=i.order_id WHERE i.company_id=c.id AND o.user_id=? AND o.status<>'CANCELLED') ORDER BY f.created_at DESC LIMIT 30",user.id());}
 private void purchased(long company,long customer,boolean delivered){String condition=delivered?"m.status='DELIVERED'":"true";if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM merchant_orders m JOIN orders o ON o.id=m.order_id WHERE m.company_id=? AND o.user_id=? AND "+condition+")",Boolean.class,company,customer)))throw MarketplaceController.fail(HttpStatus.FORBIDDEN,delivered?"Feedback is available after delivery.":"Contact is available for stores you purchased from.");}
 public record Message(@NotBlank @Size(max=2000) String body){}
 @GetMapping("/api/customer/stores/{id}/messages") public List<Map<String,Object>> messages(@PathVariable long id,@AuthenticationPrincipal AccountService.Principal user){purchased(id,user.id(),false);return thread(id,user.id());}
 private List<Map<String,Object>> thread(long company,long customer){return db.queryForList("SELECT id,body,sender_id,created_at FROM (SELECT id,body,sender_id,created_at FROM store_messages WHERE company_id=? AND customer_id=? ORDER BY id DESC LIMIT 100) latest ORDER BY id",company,customer);}
 @PostMapping("/api/customer/stores/{id}/messages") @Transactional public void message(@PathVariable long id,@AuthenticationPrincipal AccountService.Principal user,@Valid @RequestBody Message p){lockFavorites(user.id());purchased(id,user.id(),false);db.update("INSERT INTO store_messages(company_id,customer_id,sender_id,body) VALUES (?,?,?,?)",id,user.id(),user.id(),p.body().trim());}
 public record Review(@Min(1) @Max(5) int rating,@NotBlank @Size(max=1500) String body){}
 @GetMapping("/api/customer/stores/{id}/review") public List<Map<String,Object>> review(@PathVariable long id,@AuthenticationPrincipal AccountService.Principal user){return db.queryForList("SELECT rating,body FROM store_reviews WHERE company_id=? AND customer_id=?",id,user.id());}
 @PutMapping("/api/customer/stores/{id}/review") @Transactional public void review(@PathVariable long id,@AuthenticationPrincipal AccountService.Principal user,@Valid @RequestBody Review p){lockFavorites(user.id());purchased(id,user.id(),true);db.update("INSERT INTO store_reviews(company_id,customer_id,rating,body) VALUES (?,?,?,?) ON CONFLICT(company_id,customer_id) DO UPDATE SET rating=excluded.rating,body=excluded.body,updated_at=CURRENT_TIMESTAMP",id,user.id(),p.rating(),p.body().trim());}
 @DeleteMapping("/api/customer/stores/{id}/review") @Transactional public void deleteReview(@PathVariable long id,@AuthenticationPrincipal AccountService.Principal user){db.update("DELETE FROM store_reviews WHERE company_id=? AND customer_id=?",id,user.id());}
 private long merchant(long user){var rows=db.queryForList("SELECT company_id FROM merchant_stores WHERE user_id=?",user);if(rows.isEmpty())throw MarketplaceController.fail(HttpStatus.NOT_FOUND,"Store not found.");return ((Number)rows.get(0).get("company_id")).longValue();}
 @GetMapping("/api/merchant/conversations") public List<Map<String,Object>> conversations(@AuthenticationPrincipal AccountService.Principal user){return db.queryForList("SELECT customer_id,max(created_at) AS updated_at FROM store_messages WHERE company_id=? GROUP BY customer_id ORDER BY updated_at DESC LIMIT 100",merchant(user.id()));}
 @GetMapping("/api/merchant/reviews") public List<Map<String,Object>> storeReviews(@AuthenticationPrincipal AccountService.Principal user){return db.queryForList("SELECT customer_id,rating,body,updated_at FROM store_reviews WHERE company_id=? ORDER BY updated_at DESC LIMIT 100",merchant(user.id()));}
 @GetMapping("/api/merchant/conversations/{id}") public List<Map<String,Object>> conversation(@PathVariable long id,@AuthenticationPrincipal AccountService.Principal user){long company=merchant(user.id());purchased(company,id,false);return thread(company,id);}
 @PostMapping("/api/merchant/conversations/{id}") @Transactional public void reply(@PathVariable long id,@AuthenticationPrincipal AccountService.Principal user,@Valid @RequestBody Message p){lockFavorites(user.id());long company=merchant(user.id());purchased(company,id,false);db.update("INSERT INTO store_messages(company_id,customer_id,sender_id,body) VALUES (?,?,?,?)",company,id,user.id(),p.body().trim());}
 @GetMapping("/api/customer/deliveries/{number}") public List<Map<String,Object>> deliveries(@PathVariable String number,@AuthenticationPrincipal AccountService.Principal user){return db.queryForList("SELECT c.id AS company_id,c.name,m.status FROM merchant_orders m JOIN orders o ON o.id=m.order_id JOIN companies c ON c.id=m.company_id WHERE o.order_number=? AND o.user_id=? ORDER BY c.id",number,user.id());}
}
